/* ── Securite ───────────────────────────────────────────────────────────── */
function esc(s) {
  return String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;')
    .replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}

/* ── Rendu d'un orphelin (Kit BO V5 — T-02 Option B : zéro CSS module) ──── */
function renderItem(item) {
  const hasCand = item.candidats.length > 0;
  const accentCls = hasCand ? 'bo-accent-success' : 'bo-accent-danger';

  const corpusHtml = item.corpus.slice(0, 15).map(t =>
    `<span class="badge text-bg-light border me-1 mb-1 fw-normal">${esc(t)}</span>`
  ).join('') + (item.corpus.length > 15
    ? `<span class="badge text-bg-light border text-muted me-1 mb-1 fw-normal">+${item.corpus.length - 15}</span>` : '');

  let candsHtml = '';
  if (hasCand) {
    candsHtml = item.candidats.map((c, ci) => `
      <label class="d-flex gap-2 align-items-start p-2 border rounded mb-1" data-cv="cand" id="lbl-${esc(item.id)}-${ci}">
        <input type="checkbox" value="${ci}"
               class="form-check-input flex-shrink-0 mt-1" data-cv="cr" data-iid="${esc(item.id)}">
        <div class="flex-grow-1 overflow-hidden">
          <span class="fw-bold text-primary me-1">${esc(c.code_ccam)}</span>
          <span class="text-muted small">ch.${esc(c.chapitre)}</span>
          <span class="badge bg-warning text-dark ms-1">score ${c.score}</span>
          <span class="badge bg-light text-dark border ms-1">rang ${ci + 1}</span>
          <div class="text-truncate mt-1" title="${esc(c.libelle)}">${esc(c.libelle)}</div>
          <div class="mt-1">${c.termes.map(t =>
            `<span class="badge text-bg-success me-1 mb-1 fw-normal">${esc(t)}</span>`).join('')}</div>
        </div>
      </label>`).join('');
  } else {
    candsHtml = `<p class="text-muted small mb-0 fst-italic">
      <i class="bi bi-x-circle text-danger"></i>
      Aucun candidat CCAM (score &lt; 2).
      Termes recherches : ${esc(item.corpus.slice(0,6).join(', '))}
      ${item.corpus.length > 6 ? '...' : ''}</p>`;
  }

  const speBadge = item.specialite
    ? `<span class="badge bg-light text-dark border me-1">${esc(item.specialite)}</span>` : '';

  return `<div class="card bo-card ${accentCls} mb-2" data-cv="card"
               data-id="${esc(item.id)}"
               data-spe="${esc(item.specialite)}"
               data-lib="${esc(item.libelle_cible.toLowerCase())}"
               data-has="${hasCand ? 1 : 0}">
    <div class="card-body py-2 px-3">
      <div class="d-flex align-items-center flex-wrap gap-2 mb-1">
        <span class="small fw-bold text-muted">#${item.num}</span>
        <span class="badge bg-primary font-monospace">${esc(item.id_protocole)}</span>
        ${speBadge}
        <span class="fw-semibold flex-grow-1">${esc(item.libelle_cible)}</span>
        <span class="badge bg-secondary">
          <i class="bi bi-activity"></i> ${item.frequence}
        </span>
      </div>
      <div class="mb-2">${corpusHtml}</div>
      <div>${candsHtml}</div>
    </div>
  </div>`;
}

/* ── Helpers DOM ───────────────────────────────────────────────────────── */
function show(id) { const el = document.getElementById(id); if (el) el.classList.remove('d-none'); }
function hide(id) { const el = document.getElementById(id); if (el) el.classList.add('d-none'); }

/* ── Logique interne (activée quand isAdmin) ──────────────────────────── */
function initValidator() {
  const listEl = document.getElementById('list');
  if (!listEl) return;
  listEl.innerHTML = DATA.map(renderItem).join('');

  function updateStats() {
    const cards    = [...document.querySelectorAll('[data-cv="card"]')];
    const withC    = cards.filter(c => c.dataset.has === '1').length;
    const checked  = [...document.querySelectorAll('[data-cv="cr"]:checked')];
    const nbLinks  = checked.length;
    const nbProtos = new Set(checked.map(cb => cb.dataset.iid)).size;
    document.getElementById('stat-total').textContent   = DATA.length + ' orphelins';
    document.getElementById('stat-with').textContent    = withC + ' avec candidats';
    document.getElementById('stat-without').textContent = (DATA.length - withC) + ' sans candidat';
    document.getElementById('stat-sel').textContent     = nbLinks + ' liens / ' + nbProtos + ' protocoles';
  }
  updateStats();

  /* Highlight label selon état checkbox (Kit BO + utilitaires BS) */
  listEl.addEventListener('change', e => {
    if (e.target.dataset.cv !== 'cr') return;
    const lbl = e.target.closest('[data-cv="cand"]');
    if (lbl) {
      lbl.classList.toggle('bg-success-subtle', e.target.checked);
      lbl.classList.toggle('border-success', e.target.checked);
    }
    /* Accent card : primary dès qu'une case cochée dans la carte, sinon retour success/danger */
    const card = e.target.closest('[data-cv="card"]');
    if (card) {
      const hasSel = !!card.querySelector('[data-cv="cr"]:checked');
      card.classList.toggle('bo-accent-primary', hasSel);
      card.classList.toggle('bo-accent-success', !hasSel && card.dataset.has === '1');
      card.classList.toggle('bo-accent-danger',  !hasSel && card.dataset.has === '0');
    }
    updateStats();
  });

  /* ── Filtres ──────────────────────────────────────────────────────── */
  function applyFilters() {
    const spe    = document.getElementById('f-spe').value.toUpperCase();
    const cand   = document.getElementById('f-cand').value;
    const search = document.getElementById('f-search').value.toLowerCase();

    document.querySelectorAll('[data-cv="card"]').forEach(card => {
      let visible = true;
      if (spe && !card.dataset.spe.toUpperCase().includes(spe)) visible = false;
      if (search && !card.dataset.lib.includes(search)) visible = false;
      if (cand === 'with'    && card.dataset.has !== '1') visible = false;
      if (cand === 'without' && card.dataset.has !== '0') visible = false;
      if (cand === 'sel' && !card.querySelector('[data-cv="cr"]:checked')) visible = false;
      card.classList.toggle('d-none', !visible);
    });
  }

  ['f-spe','f-cand','f-search'].forEach(id =>
    document.getElementById(id).addEventListener('input', applyFilters));

  /* ── Export SQL ────────────────────────────────────────────────────── */
  document.getElementById('btn-export').addEventListener('click', () => {
    const lines = [];
    let countLinks = 0, countProtos = 0;

    DATA.forEach(item => {
      const checked = [...document.querySelectorAll(`[data-cv="cr"][data-iid="${item.id}"]:checked`)];
      if (checked.length === 0) return;
      countProtos++;
      lines.push(`-- ${item.id_protocole} | ${item.libelle_cible} (freq ${item.frequence})`);
      checked.forEach(cb => {
        const ci   = parseInt(cb.value, 10);
        const cand = item.candidats[ci];
        if (!cand) return;
        const rang = ci + 1;
        lines.push(`--   rang ${rang} : ${cand.code_ccam} score:${cand.score} | ${cand.libelle.slice(0,70)}`);
        lines.push(`INSERT INTO protocole_ccam (protocole_id, ccam_acte_id, rang)`);
        lines.push(`  VALUES ('${item.id}', '${cand.id}', ${rang});`);
        countLinks++;
      });
      lines.push('');
    });

    const header = countLinks > 0
      ? `-- CCAM Validator export -- ${new Date().toISOString().slice(0,19)}\n-- ${countLinks} lien(s) sur ${countProtos} protocole(s)\n-- Le trigger trg_sync_codes_ccam met a jour codes_ccam automatiquement\n\nBEGIN;\n\n`
      : '';
    const footer = countLinks > 0 ? '\nCOMMIT;\n' : '';
    const sql    = countLinks > 0
      ? header + lines.join('\n') + footer
      : '-- Aucune selection\n-- Cocher au moins un candidat CCAM par orphelin.';

    document.getElementById('sql-output').value = sql;
    document.getElementById('sql-stats').textContent =
      countLinks > 0
        ? `${countLinks} lien(s) sur ${countProtos} protocole(s). Le trigger sync_codes_ccam se declenchera automatiquement.`
        : 'Aucune selection — cocher au moins un candidat par orphelin.';

    new bootstrap.Modal(document.getElementById('modal-sql')).show();
  });

  document.getElementById('btn-copy').addEventListener('click', () => {
    const ta = document.getElementById('sql-output');
    navigator.clipboard.writeText(ta.value).catch(() => { ta.select(); document.execCommand('copy'); });
    const btn = document.getElementById('btn-copy');
    btn.innerHTML = '<i class="bi bi-check"></i> Copie !';
    setTimeout(() => btn.innerHTML = '<i class="bi bi-clipboard"></i> Copier', 2000);
  });
}

/* ── Orchestration (pattern conseil-app.js) ──────────────────────────── */
document.addEventListener('DOMContentLoaded', () => {

  (async () => {
    await window.bdbShellReady;
    if (!window.bdbUser) return;
    hide('cv-loading');
    if (!window.bdbUser.isAdmin) {
      document.getElementById('cv-denied').classList.remove('d-none');
      return;
    }
    document.getElementById('cv-content').classList.remove('d-none');
    initValidator();
  })();

});
